"""Ribbon UX rework of HST Slides and HST Draw (hst-ribbon-ux-impress-draw.patch, generated by
scripts/patches/generate-ribbon-ux-impress-draw.py, and hst-ribbon-ux-impress-draw-commands.patch). Reads the
patches; the group helpers are exercised on a small notebookbar fragment."""
import os
import re
import sys
import unittest

from _paths import ROOT

sys.path.insert(0, os.path.join(ROOT, "scripts", "patches"))
import ribbon_ux_lib as L  # noqa: E402
from ribbon_ux_impress_draw_builder import Builder  # noqa: E402
from ribbon_ux_impress_draw_data import (  # noqa: E402
    DESCRIPTIONS, DRAW_SUPPR, DRAW_UI, IMPRESS_SUPPR, IMPRESS_UI, LABELS, STRINGS, VI_PO)

PATCHES = os.path.join(ROOT, "patches", "libreoffice")


def read(name):
    with open(os.path.join(PATCHES, name), encoding="utf-8") as handle:
        return handle.read()


def section(text, path):
    start = text.index(f"+++ b/{path}\n")
    end = text.find("\n--- a/", start)
    return text[start:end if end >= 0 else len(text)]


def lines(text, sign):
    return [line[1:] for line in text.splitlines() if line.startswith(sign) and not line.startswith(sign * 3)]


class RibbonUxImpressDrawPatch(unittest.TestCase):
    patch = read("hst-ribbon-ux-impress-draw.patch")
    impress = section(patch, IMPRESS_UI)
    draw = section(patch, DRAW_UI)
    po = section(patch, VI_PO)

    def test_every_new_string_has_its_vietnamese(self):
        added_ui = "\n".join(lines(self.impress, "+") + lines(self.draw, "+"))
        # strings this patch introduces (moved lines keep their older contexts)
        props = re.findall(r'translatable="yes" context="([^"]+\|hst(?:UX|Ribbon)[^"]*)">([^<]+)<', added_ui)
        self.assertTrue(props)
        for context, msgid in props:
            msgid = msgid.replace("&amp;", "&")
            self.assertRegex(self.po, re.escape(f'+msgctxt "{context}"\n+msgid "{msgid}"\n+msgstr "') + r'[^"]+"',
                             (context, msgid))

    def test_vietnamese_terms(self):
        msgstrs = re.findall(r'^\+msgstr "(.*)"$', self.po, re.M)
        self.assertGreater(len(msgstrs), 60)
        for text in msgstrs:
            for wrong in ("Vĩ lệnh", "vĩ lệnh", "Canh ", "canh ", "Hoạt ảnh", "Basic", "Phối thư", "Nhạc", " & "):
                self.assertNotIn(wrong, text)
            for brand in ("Microsoft", "PowerPoint", "Excel", "Word "):
                self.assertNotIn(brand, text)
        self.assertEqual(LABELS["audio_video"][1], "Âm thanh và video")
        self.assertEqual(STRINGS["lbExtensionHstDeveloper"][2], "Nhà phát triển")
        self.assertEqual(STRINGS["ExportLabel"][2], "P~DF")

    def test_slides_layout(self):
        added = "\n".join(lines(self.impress, "+"))
        removed = "\n".join(lines(self.impress, "-"))
        for gid in ("gdHomeHstEditing", "gdExtensionHstDeveloper"):
            self.assertIn(f'id="{gid}"', added)
        # the "Tab ▾" blocks and the Home "Công cụ ▾" block are gone; Tương tác left Hoạt hình
        for block in ("Home-Menu", "Insert-Menu", "Layout-Menu", "Slideshow-Menu", "Reference-Menu", "View-Menu",
                      "Table-Menu", "Draw-Menu", "Object-Menu",
                      "bxHstAnimationEffects8", "gdViewHstMacros", "gdToolsMacro", "bxReviewHyphenation"):
            self.assertIn(f'id="{block}"', removed, block)
            self.assertNotIn(f'id="{block}"', added, block)
        self.assertIn('id="btnHomeInsertSlide"', added)
        self.assertIn(".uno:InsertPage", added)
        self.assertIn('id="btnHstHomeShapes:Menu HstShapes"', added)
        for command in (".uno:HstApplyTransitionToAll", ".uno:HstPreviewTransition", ".uno:HstPreviewAnimation",
                        ".uno:HstSetTransitionDuration", ".uno:HstSetTransitionAdvance",
                        ".uno:TableSort", ".uno:EqualizeWidth", ".uno:Connect", ".uno:Morphing"):
            self.assertIn(f'"action-name">{command}<', added, command)
        self.assertIn("Văn bản&#10;hành chính mới", added)  # glade writes the line break as a reference

    def test_draw_layout(self):
        added = "\n".join(lines(self.draw, "+"))
        for oid in ("gdHomeHstPdfEdit", "btnHstArrangeAlign", "btnHstArrangeTransform:Menu HstTransform",
                    "btnHstViewSnap:Menu HstSnap"):
            self.assertIn(f'id="{oid}"', added)
        self.assertNotIn("btnHstHomeShapes", added)  # the vertical drawing bar keeps the shapes
        self.assertIn('context="TabbedDraw|hstUXExportTabLabel">P~DF<', added)
        self.assertEqual(len(re.findall(r'class="GtkCheckMenuItem" id="MenuHstSnap-', added)), 9)

    def test_gla11y_lines_follow_the_buttons(self):
        for suppr, ui, bid in ((IMPRESS_SUPPR, IMPRESS_UI, "btnHstHomeFind"), (DRAW_SUPPR, DRAW_UI, "btnHstPdfEditText")):
            self.assertIn(f"+{ui}://GtkToolButton[@id='{bid}'] button-no-label", section(self.patch, suppr))
        self.assertIn(f"-{IMPRESS_UI}://GtkToolButton[@id='btnReviewHyphenation'] button-no-label",
                      section(self.patch, IMPRESS_SUPPR))

    def test_descriptions_are_short_sentences(self):
        for command, (english, vietnamese) in DESCRIPTIONS.items():
            self.assertTrue(english.endswith(".") and vietnamese.endswith("."), command)
            self.assertLess(len(vietnamese), 110, command)
        self.assertGreaterEqual(len(DESCRIPTIONS), 40)


class CommandsPatch(unittest.TestCase):
    patch = read("hst-ribbon-ux-impress-draw-commands.patch")

    def test_drawing_toolbar_hidden_in_slides_only(self):
        xcu = section(self.patch, "officecfg/registry/data/org/openoffice/Office/UI/ImpressWindowState.xcu")
        self.assertIn("-          <value>true</value>\n+          <value>false</value>", xcu)
        self.assertNotIn("DrawWindowState", self.patch)

    def test_effect_commands_are_wired(self):
        for name, sid in (("HstApplyTransitionToAll", "SID_HST_TRANSITION_APPLY_ALL"),
                          ("HstPreviewTransition", "SID_HST_TRANSITION_PREVIEW"),
                          ("HstPreviewAnimation", "SID_HST_ANIMATION_PREVIEW")):
            self.assertIn(f"+SfxVoidItem {name} {sid}", section(self.patch, "sd/sdi/sdraw.sdi"))
            self.assertIn(f"+    {sid}\n", section(self.patch, "sd/sdi/drviewsh.sdi"))
            self.assertIn(f'+      <node oor:name=".uno:{name}" oor:op="replace">',
                          section(self.patch, "officecfg/registry/data/org/openoffice/Office/UI/DrawImpressCommands.xcu"))
            self.assertIn(f"..uno:{name}\\n", section(
                self.patch, "translations/source/vi/officecfg/registry/data/org/openoffice/Office/UI.po"))
        self.assertIn('+msgstr "Áp dụng cho tất cả"', self.patch)
        for impl, command in (("HstTransitionDurationControl", ".uno:HstSetTransitionDuration"),
                              ("HstTransitionAdvanceControl", ".uno:HstSetTransitionAdvance")):
            self.assertIn(f'<implementation name="com.sun.star.comp.sd.{impl}"', self.patch)
            self.assertIn(f"+          <value>{command}</value>", self.patch)
            self.assertIn(f"com_sun_star_comp_sd_{impl}_get_implementation", self.patch)
        self.assertTrue(all(f'+msgstr "{vi}"' in self.patch for vi in ("Tự chuyển sau", "Thời lượng")))
        self.assertIn("+\tsd/source/ui/animations/HstSlideEffectCommands \\", self.patch)

    def test_sidebar_folds_once_on_first_start(self):
        self.assertIn('SlidesSidebarFirstStartDone" oor:type="xs:boolean"', self.patch)
        sidebar = section(self.patch, "sfx2/source/sidebar/SidebarController.cxx")
        self.assertIn('"com.sun.star.presentation.PresentationDocument"', sidebar)
        self.assertIn("+        RequestCloseDeck();", sidebar)

    def test_theme_names(self):
        cxx = section(self.patch, "svx/source/dialog/ThemeColorsPaneBase.cxx")
        self.assertIn("hstThemeDisplayName(rColorSet.getName())", cxx)
        self.assertIn("C\\u1ea7u v\\u1ed3ng", cxx)  # Cầu vồng
        ui = section(self.patch, "svx/uiconfig/ui/themeselectorpanel.ui")
        self.assertIn('+        <property name="height-request">88</property>', ui)


class GroupHelpers(unittest.TestCase):
    UI = """<interface>
  <object class="GtkGrid" id="NotebookBar">
    <child>
      <object class="sfxlo-PriorityMergedHBox" id="pmhbHome">
        <child>
          <object class="GtkGrid" id="gdOld">
            <child>
              <object class="GtkLabel" id="lbOld"><property name="label">Old</property></object>
              <packing><property name="left-attach">0</property><property name="top-attach">2</property></packing>
            </child>
            <child>
              <object class="sfxlo-NotebookbarToolBox" id="bxOld">
                <child><object class="GtkToolButton" id="btnA"><property name="action-name">.uno:Cut</property></object></child>
                <child><object class="GtkToolButton" id="btnB"><property name="action-name">.uno:Copy</property></object></child>
              </object>
              <packing><property name="left-attach">0</property><property name="top-attach">0</property></packing>
            </child>
          </object>
          <packing><property name="position">0</property></packing>
        </child>
      </object>
    </child>
  </object>
</interface>"""

    def test_refill_keeps_the_caption_and_spans_the_columns(self):
        b = Builder(L.parse_text(self.UI), "impress")
        cut, copy = b.take("btnA", "btnB")
        grid = b.refill("gdOld", [("L", [cut]), ("S", [copy], None, "both-horiz")], "lbHomeHstEditing")
        caption = [c for c in grid if c.tag == "child" and c.find("object").get("id") == "lbOld"][0]
        self.assertEqual(L.packing(caption, "width"), "2")
        self.assertEqual(L.prop(L.find(b.root, "lbOld"), "label"), "Editing")
        self.assertIn((STRINGS["lbHomeHstEditing"][0], "Editing"), b.strings)
        L.check_unique(b.root)

    def test_new_group_and_errors(self):
        b = Builder(L.parse_text(self.UI), "impress")
        b.insert_group("pmhbHome", b.new_group("gdNew", "lbNew", "lbHomeHstEditing", [("L", b.take("btnA"))]),
                       first=True)
        b.renumber()
        box = L.find(b.root, "pmhbHome")
        self.assertEqual([c.find("object").get("id") for c in box.findall("child")], ["gdNew", "gdOld"])
        L.check_unique(b.root)
        with self.assertRaises(L.RibbonUxError):
            b.take("btnMissing")
        with self.assertRaises(L.RibbonUxError):
            b.refill("bxOld", [])  # a toolbox has no caption


if __name__ == "__main__":
    unittest.main()
